<script>
import jsbarcode from 'jsbarcode'
import setter from '@/libs/setter.js'
import {
  Query,
  Aud
} from '@api/shuju.js'
export default {
  name: 'Chuku',
  components: {

  },
  data() {
    return {
      fullscreenLoading: false,
      loading: false,
      formData: {
        name: '',
        date: '',
        ddbh: '',
        fkfs: '',
        khmc: '',
        zje: '',
        djlx: ''
      },
      formRules: {

      },
      findList: [],
      fkfsList: [
        { value: '支付宝', label: '支付宝' },
        { value: '微信', label: '微信' },
        { value: '转账', label: '转账' },
        { value: '现金', label: '现金' },
      ],
      dialogTableVisible: false,
      dialogTableVisible2: false,
      isShow: true,
      dwmc: '',
      yhmz: '',
      jedx: '',
      fyjq: [],
      nameList: [],
      khList: [],
      cpList: [],
      yhList: [],
      tableData: [],
      tableData2: [],
      nowView: 2,
      heji: [],
      jesz: [],
      passID: null,
      authKeys: [],
      tablePage: { // 分页属性---
        currentPage: 1, //当前页 相当于layui的page
        pageSize: 10,  	//每页条数 相当于layui的limt
        totalResult: 0  //总页数   相当于count				
      },
      //搜索变量
      searchFilter: {
        name: '',
        //account: '',
        disable: ''
      },


    }
  },
  /* props: {
        passID: Number,	
        authKeys: String,		
        }, */
  mounted() {
    this.checkDev()
    this.getcpData()
    this.InitCginfo()
    this.getkhData()
    this.getyhData()
    // this.getTableData()


  },
  methods: {
    back() {
      this.$emit('goBack')
    },
    checkDev() {
      this.isDev = (process.env.NODE_ENV === 'development') ? true : false

    },
    exportDataEvent() {
      this.$refs.xTable.openExport()
    },
    sumNum(list, field) {
      let count = 0
      let zje = 0
      list.forEach(item => {
        count += Number(item[field])
        zje += Number(item['金额'])
      })
      this.formData.zje = zje
      console.log(this.formData.zje)
      return count
    },

    footerMethod({ columns, data }) {

      const footerData = [
        columns.map((column, columnIndex) => {
          if (columnIndex === 0) {
            return '合计'
          }
          if (['数量', '金额'].includes(column.property)) {
            let zje = 0
            let ndata = data.map(function (v, i) {
              let je = v.数量 * v.单价
              return Object.assign(v, { 金额: je });
            })


            return this.sumNum(ndata, column.property)
          }

          return null
        })
      ]
      this.heji = footerData
      return footerData

    },
    dakai() {

      this.getTableData()
      this.dialogTableVisible = true

    },
    add() {
      let xzsj = this.$refs.xTable1.getCurrentRecord()
      // let bgsj =  this.$refs.xTable.getTableData()
      console.log(xzsj)
      this.passID = xzsj.id
      this.InitCginfo()
      this.dialogTableVisible = false
    },
    del() {
      this.deleteInfo()
      /* const $grid = this.$refs.xTable
      $grid.removeCheckboxRow() */

    },
    addduo() {
      const $grid2 = this.$refs.xTable1
      const $grid = this.$refs.xTable
      let sj = $grid2.getCheckboxRecords().map(function (v, i) {
        delete v.id
        delete v.日期
        return v
      })
      console.log(sj)
      $grid.insertAt(sj, -1)

      let xsz = setter.getTime().split(' ');
      let xx = xsz[1].split(':');//用split()函数将字符串分割成数组，（）里面的参数是分割条件;
      let xs = xsz[0].split('-');//用split()函数将字符串分割成数组，（）里面的参数是分割条件;
      let bh = xs[0] + xs[1] + xs[2] + xx[0] + xx[1] + xx[2];
      /* if (this.passID === '') {
        console.log(this.passID)
      this.formData.ddbh = 'CGRK' + bh;
      this.formData.djlx = '采购入库'; 
       this.formData.date = xsz[0]
      } */
      this.dialogTableVisible = false
    },
    cellClickEvent({ column, row }) {
      /* console.log(`单元格点击${column.title}`)
      console.log(column.title)
      console.log(row) */
    },
    async test() {
      let bgsj = this.$refs.xTable.getTableData().tableData
      console.log(bgsj)
      for (let x of bgsj) {
        let i = 1
        i += i
        let tjc = `货位号='${x.货位号}' and 库存数量>=0`;
        await Query({
          tablename: '查询库存',
          field: 'id',
          tj: tjc  //加载条件					
        }).then(result55 => {
          console.log(result55.data)
          if (result55.data.length == 0) {
            this.$message.error('库存不存在，请核对库存')
          } else if (result55.data.length > 0) {
            let hhh = result55.data;
            let cfz = hhh.map(function (va1, in2) {  // 货位号的货位ID
              return va1.产品ID;
            });
            let zd = cfz.indexOf(x.产品ID)
            console.log(zd);
            if (zd >= 0) {
              if (x.完成 != -1) {
                let sl = isNaN(Number(x.数量)) ? 0 : Number(x.数量);
                let rk = isNaN(Number(hhh[zd].入库数量)) ? 0 : Number(hhh[zd].入库数量);
                let ck = isNaN(Number(hhh[zd].出库数量)) ? 0 : Number(hhh[zd].出库数量);
                console.log(ck);
                let cksl = sl + ck;
                console.log(cksl);
                if (rk - cksl >= 0) {
                  Aud({
                    reqType: 'update',
                    //content:`{id:${hhh[zd].id} ,出库数量:${cksl}}`,
                    content: [{ id: hhh[zd].id, 出库数量: cksl }],
                    tablename: '库存'
                  })
                    .then(result30 => {
                      this.$message.success('库存已减少')
                      this.wancheng(x.id);
                    }).catch(err => {
                      //this.fullscreenLoading = false
                    })

                } else {

                  this.$message.error(`第${i + 1}条,` + '出库数量不能大于库存')
                }
              } else {

                this.$message.success(`前${i}条明细已完成出库`)
              }
            } else {
              this.$message.error('此货位已占用')
            }
          }
        }).catch(err => {

        })

      }
    },
    gxsj({ row, rowIndex, $rowIndex, column, columnIndex, $columnIndex }) {
      console.log(column.title)
      console.log(row)

      if (row.id) {
        let up = [{ 'id': row.id }]
        /* let jeobj
        let upobj = {[column.title]:row[column.title]}
        if(upobj){
           Object.assign(up[0],upobj);
        }
         if (['数量', '单价'].includes(column.title)) {
           jeobj = {金额:row.单价*row.数量}                                 
            Object.assign(up[0],jeobj);
        }  */
        if (['货位号'].includes(column.title)) {
          Object.assign(up[0], { 货位号: row.货位号 });
        }
        console.log(up)
        if (row.完成 != -1) {
          Aud({
            reqType: 'update',
            content: up,
            tablename: '出单'
          })
            .then(res => {
              //this.fullscreenLoading = false
              this.$message.success('修改成功')
              //	this.$emit('goBack')
            })
            .catch(err => {
              //this.fullscreenLoading = false
            })
        } else {
          this.$message.error('此条明细已完成出库，修改失败')
        }

      }
    },
    wancheng(id) {
      let xsz = setter.getTime().split(' ');
      let bgsj = this.$refs.xTable.getTableData().tableData
      console.log(bgsj)
      let obj42 = bgsj.find(o => o.id === id);
      Aud({     //后台数据提交

        reqType: 'update',
        content: [{ id: id, 完成: -1, 日期: xsz[0] }],
        //content:`{id: ${id} ,完成:-1}`,
        tablename: '出单'
      })
        .then(result3 => {
          let _this = this
          console.log(result3)
          Object.assign(obj42, { 完成: -1 });
          console.log(obj42.货位号)
          _this.caigou(obj42.单据编号);

        }).catch(err => {
          //this.fullscreenLoading = false
        })
    },
    caigou(bh) { //刷新
      let wch
      let tj22 = `单据编号 = '${bh}'`
      Query({
